#!/usr/bin/env python3
"""Turns an atlas made by gen.html (out/<name>.png + out/<name>.json) into a
C++ header with the sprite rectangles and the PNG bytes.

Usage: make_header.py out/th06_menu src/PointDeviceArt.hpp
"""
import json
import struct
import sys

base, header = sys.argv[1], sys.argv[2]
rects = json.load(open(base + ".json"))
png = open(base + ".png", "rb").read()
width, height = struct.unpack(">II", png[16:24])
scale = 2

lines = [
    "#pragma once",
    "",
    "// Generated by tools/pointdevice-art/make_header.py from gen.html; do not edit by hand.",
    "// The Pointdevice menu art: one atlas drawn at %dx the game's 640x480 coordinates." % scale,
    "",
    '#include "inttypes.hpp"',
    "",
    "namespace PointDeviceArt",
    "{",
    "struct Sprite",
    "{",
    "    const char *name;",
    "    // Atlas pixels.",
    "    u16 x, y, w, h;",
    "    // Game pixels: where the content origin sits inside the sprite, the",
    "    // sprite's size, the content's size, and where an English caption ends.",
    "    f32 originX, originY, width, height, contentWidth, contentHeight, captionEnd;",
    "};",
    "",
    "static const i32 kAtlasWidth = %d;" % width,
    "static const i32 kAtlasHeight = %d;" % height,
    "",
    "// clang-format off",
    "static const Sprite kSprites[] = {",
]
for name in sorted(rects):
    r = rects[name]
    lines.append(
        '    {"%s", %d, %d, %d, %d, %.2ff, %.2ff, %.2ff, %.2ff, %.2ff, %.2ff, %.2ff},'
        % (name, r["x"], r["y"], r["w"], r["h"], r["ox"], r["oy"], r["lw"], r["lh"], r["cw"], r["ch"], r.get("enEnd", 0))
    )
lines.append("};")
lines.append("")
lines.append("static const u8 kAtlasPng[] = {")
for i in range(0, len(png), 24):
    lines.append("    " + ",".join("0x%02x" % b for b in png[i : i + 24]) + ",")
lines.append("};")
lines.append("// clang-format on")
lines.append("} // namespace PointDeviceArt")
open(header, "w").write("\n".join(lines) + "\n")
print(header, len(rects), "sprites", width, "x", height, len(png), "bytes")
